257: func (gw *Gateway) doAddOrUpdate(keyName string, newSession *user.SessionState, dontReset bool, isHashed bool) error {
258: 	// field last_updated plays an important role in in-mem rate limiter
259: 	// so update last_updated to current timestamp only if suppress_reset wasn't set to 1
260: 	if !dontReset {
261: 		newSession.LastUpdated = strconv.Itoa(int(time.Now().Unix()))
262: 	}
263: 
264: 	if len(newSession.AccessRights) > 0 {
265: 		// reset API-level limit to empty APILimit if any has a zero-value
266: 		resetAPILimits(newSession.AccessRights)
267: 		// We have a specific list of access rules, only add / update those
268: 
269: 		for apiId := range newSession.AccessRights {
270: 			apiSpec := gw.getApiSpec(apiId)
271: 			if apiSpec == nil {
272: 				log.WithFields(logrus.Fields{
273: 					"prefix":      "api",
274: 					"key":         keyName,
275: 					"org_id":      newSession.OrgID,
276: 					"api_id":      apiId,
277: 					"user_id":     "system",
278: 					"user_ip":     "--",
279: 					"path":        "--",
280: 					"server_name": "system",
281: 				}).Error("Could not add key for this API ID, API doesn't exist.")
282: 				return errors.New("API must be active to add keys")
283: 			}
284: 			gw.checkAndApplyTrialPeriod(keyName, newSession, isHashed)
285: 
286: 			// Lets reset keys if they are edited by admin
287: 			if !apiSpec.DontSetQuotasOnCreate {
288: 				// Reset quote by default
289: 				if !dontReset {
290: 					gw.GlobalSessionManager.ResetQuota(keyName, newSession, isHashed)
291: 					newSession.QuotaRenews = time.Now().Unix() + newSession.QuotaRenewalRate
292: 				}
293: 
294: 				// apply polices (if any) and save key
295: 				if err := gw.applyPoliciesAndSave(keyName, newSession, apiSpec, isHashed); err != nil {
296: 					return err
297: 				}
298: 			}
299: 		}
300: 	} else {
301: 		// nothing defined, add key to ALL
302: 		if !gw.GetConfig().AllowMasterKeys {
303: 			log.Error("Master keys disallowed in configuration, key not added.")
304: 			return errors.New("Master keys not allowed")
305: 		}
306: 		log.Warning("No API Access Rights set, adding key to ALL.")
307: 		gw.apisMu.RLock()
308: 		defer gw.apisMu.RUnlock()
309: 		for _, spec := range gw.apisByID {
310: 			if !dontReset {
311: 				gw.GlobalSessionManager.ResetQuota(keyName, newSession, isHashed)
312: 				newSession.QuotaRenews = time.Now().Unix() + newSession.QuotaRenewalRate
313: 			}
314: 			gw.checkAndApplyTrialPeriod(keyName, newSession, isHashed)
315: 
316: 			// apply polices (if any) and save key
317: 			if err := gw.applyPoliciesAndSave(keyName, newSession, spec, isHashed); err != nil {
318: 				return err
319: 			}
320: 		}
321: 	}
322: 
323: 	log.WithFields(logrus.Fields{
324: 		"prefix":      "api",
325: 		"key":         gw.obfuscateKey(keyName),
326: 		"expires":     newSession.Expires,
327: 		"org_id":      newSession.OrgID,
328: 		"api_id":      "--",
329: 		"user_id":     "system",
330: 		"user_ip":     "--",
331: 		"path":        "--",
332: 		"server_name": "system",
333: 	}).Info("Key added or updated.")
334: 	return nil
335: }
