354: func (gw *Gateway) handleAddOrUpdate(keyName string, r *http.Request, isHashed bool) (interface{}, int) {
355: 	suppressReset := r.URL.Query().Get("suppress_reset") == "1"
356: 
357: 	// decode payload
358: 	newSession := &user.SessionState{}
359: 
360: 	contents, _ := ioutil.ReadAll(r.Body)
361: 	r.Body = ioutil.NopCloser(bytes.NewReader(contents))
362: 
363: 	if err := json.Unmarshal(contents, newSession); err != nil {
364: 		log.Error("Couldn't decode new session object: ", err)
365: 		return apiError("Request malformed"), http.StatusBadRequest
366: 	}
367: 
368: 	mw := BaseMiddleware{Gw: gw}
369: 	// TODO: handle apply policies error
370: 	mw.ApplyPolicies(newSession)
371: 	// DO ADD OR UPDATE
372: 
373: 	// get original session in case of update and preserve fields that SHOULD NOT be updated
374: 	originalKey := user.SessionState{}
375: 	if r.Method == http.MethodPut {
376: 		key, found := gw.GlobalSessionManager.SessionDetail(newSession.OrgID, keyName, isHashed)
377: 		keyName = key.KeyID
378: 		if !found {
379: 			log.Error("Could not find key when updating")
380: 			return apiError("Key is not found"), http.StatusNotFound
381: 		}
382: 		originalKey = key.Clone()
383: 
384: 		isCertificateChanged := newSession.Certificate != originalKey.Certificate
385: 		if isCertificateChanged {
386: 			if newSession.Certificate == "" {
387: 				log.Error("Key must contain a certificate")
388: 				return apiError("Key cannot be used without a certificate"), http.StatusBadRequest
389: 			}
390: 
391: 			// check that the certificate exists in the system
392: 			_, err := gw.CertificateManager.GetRaw(newSession.Certificate)
393: 			if err != nil {
394: 				log.Error("Key must contain an existing certificate")
395: 				return apiError("Key must be used with an existent certificate"), http.StatusBadRequest
396: 			}
397: 		}
398: 
399: 		// preserve the creation date
400: 		newSession.DateCreated = originalKey.DateCreated
401: 
402: 		// don't change fields related to quota and rate limiting if was passed as "suppress_reset=1"
